node -e "
const ExcelJS = require('exceljs');

(async () => {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Extracted Text');

  // Header row
  sheet.columns = [
    { header: 'Line', key: 'line', width: 10 },
    { header: 'Text', key: 'text', width: 70 },
  ];

  // Style header
  sheet.getRow(1).font = { bold: true };

  // Read extracted text and add rows
  const fs = require('fs');
  const text = fs.readFileSync('/workspace/testbed/docs/handbook.txt', 'utf-8');
  const lines = text.split('\n').filter(l => l.trim().length > 0);

  lines.forEach((line, i) => {
    sheet.addRow({ line: i + 1, text: line });
  });

  const outPath = '/workspace/testbed/docs/handbook_extracted.xlsx';
  await workbook.xlsx.writeFile(outPath);
  console.log('Excel file created:', outPath);
})();
"
